function pad(num) {
    return num.toString().padStart(2, '0');
}
function padMilliseconds(ms) {
    return ms.toString().padStart(3, '0');
}
export function formatLog(message) {
    const now = new Date();
    const formattedTime = `${pad(now.getHours())}:${pad(now.getMinutes())}:${pad(now.getSeconds())}:${padMilliseconds(now.getMilliseconds())}`;
    return `[VdSpek ${formattedTime}] ${message}`;
}
